public class OnlineStockSpanTest {

    @Test
    public void next_NoData_ReturnsZero() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        assertEquals(0, stockSpan.next(0));
    }

    @Test
    public void next_SingleDay_ReturnsOne() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        assertEquals(1, stockSpan.next(10));
    }

    @Test
    public void next_MultipleDays_ReturnsCorrectSpan() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        for (int i = 0; i < 10; i++) {
            stockSpan.next(i);
        }
        assertEquals(10, stockSpan.next(5));
    }

    @Test
    public void calculateSpans_EmptyArray_ReturnsEmptyArray() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] result = stockSpan.calculateSpans(new int[0]);
        assertArrayEquals(new int[0], result);
    }

    @Test
    public void calculateSpans_SingleElementArray_ReturnsCorrectSpan() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        int[] prices = {10};
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(1, result[0]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_ReturnsCorrectSpans() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        for (int i = 0; i < 10; i++) {
            stockSpan.next(i);
        }
        int[] prices = new int[]{1, 2, 3, 4, 5};
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(2, result[0]);
        assertEquals(1, result[1]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_NoStack() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        for (int i = 0; i < 10; i++) {
            stockSpan.next(i);
        }
        int[] prices = new int[]{1, 2, 3, 4, 5};
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(2, result[0]);
        assertEquals(1, result[1]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_NoNext() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        for (int i = 0; i < 10; i++) {
            stockSpan.next(i);
        }
        int[] prices = new int[]{1, 2, 3, 4, 5};
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(5, result[0]);
    }

    @Test
    public void calculateSpans_MultipleElementsArray_MockNext() {
        OnlineStockSpan stockSpan = new OnlineStockSpan();
        Stack<Integer> stack = new Stack<>();
        when(stockSpan.next(anyInt())).thenReturn(stack.push((Integer) any()));
        int[] prices = new int[]{1, 2, 3, 4, 5};
        int[] result = stockSpan.calculateSpans(prices);
        assertEquals(5, result[0]);
    }
}
